// GitHub Auditor - filtre les repos actifs et construit le payload Mistral (analyse groupee, 1 appel)
const items = $input.all().flatMap(i => i.json);
const activeRepos = items.filter(r =>
  r.archived !== true && r.disabled !== true &&
  r.permissions && (r.permissions.push || r.permissions.admin)
);
const today = new Date().toISOString().slice(0, 10);
if (activeRepos.length === 0) {
  return [{ json: { repo_count: 0, repo_list: '', audit_date: today, mistral_body: '' } }];
}
const repoSummaries = activeRepos.map((r, idx) =>
  (idx + 1) + '. **' + r.full_name + '**\n' +
  '   Description: ' + (r.description || '(aucune)') + '\n' +
  '   Langage: ' + (r.language || 'N/A') + '\n' +
  '   Topics: ' + ((r.topics && r.topics.length) ? r.topics.join(', ') : 'aucun') + '\n' +
  '   Dernier push: ' + (r.pushed_at ? r.pushed_at.slice(0, 10) : '?') + '\n' +
  '   Issues ouvertes: ' + (r.open_issues_count || 0) + '\n' +
  '   Visibilite: ' + (r.private ? 'Prive' : 'Public')
).join('\n\n');
const system = "Tu es un IA expert, un \"Architecte Collaborateur\" de code. Ta mission est de devenir le pair programmeur le plus compétent, le plus méticuleux, mais surtout le plus positif et le plus encourageant sur tous les projets GitHub que tu examines.\n\n🎯 1. Définition du Rôle et de la Philosophie (Le Ton)\nPersona : Tu es un mentor technique de niveau \"Staff Engineer\".\nTonalité Immuable : Toujours enthousiaste, ultra-constructif, respectueux.\n\n💡 2. Méthode d'Analyse\nA. Issue Thinking · B. Bug/Risque · C. Code Review · D. Pull Request\n\n📊 3. Format de Sortie\n✨ Rapport d'Audit Quotidien\n🔍 Observations · ✨ Axes d'amélioration · 🛠 Prochaine étape · ✅ Synthèse\nTermine par 🏆 Top 3 des dépôts les plus prometteurs.";
const user = 'Analyse les depots GitHub actifs suivants.\n\nListe des ' + activeRepos.length + ' depots a analyser :\n\n' + repoSummaries + '\n\nPour chaque depot : Observations, Axes d’amelioration, Prochaine etape, Synthese.\nTermine par un Top 3 des depots les plus prometteurs.';
const payload = {
  model: 'mistral-small-latest',
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  max_tokens: 3000,
  temperature: 0.3
};
return [{ json: {
  repo_count: activeRepos.length,
  repo_list: activeRepos.map(r => r.full_name).join(', '),
  audit_date: today,
  mistral_body: JSON.stringify(payload)
} }];

// GitHub Auditor - résumé Telegram + rapport complet (document) + commit markdown (base64)
const prev = $("Filtrer et préparer l'analyse").first().json;
const item = $input.first().json;
let rapport = '';
const ch = item && item.choices && item.choices[0];
if (ch && ch.message && ch.message.content) rapport = ch.message.content.trim();
if (!rapport || rapport.length < 20) {
  rapport = '⚠️ Analyse Mistral indisponible. Réponse brute : ' + JSON.stringify(item).slice(0, 800);
}
const date = prev.audit_date || new Date().toISOString().slice(0, 10);
const count = prev.repo_count || 0;
const header = '🧑‍💻 Audit GitHub — ' + count + ' dépôts analysés — ' + date;

let resume = header + '\n\n';
const topIdx = rapport.toLowerCase().lastIndexOf('top 3');
if (topIdx > 0) {
  resume += rapport.slice(topIdx);
} else {
  resume += rapport.slice(-2600);
}
resume += '\n\n📄 Rapport complet en pièce jointe + commité dans le repo GitHub-Auditor';
if (resume.length > 3400) resume = resume.slice(0, 3397) + '…';

const md = '# Audit Agent Github - ' + date + '\n\n' + rapport + '\n\n---\n*Généré par GitHub Auditor (Mistral Cloud)*\n';
return [{ json: {
  resume: resume,
  rapport_complet: rapport,
  audit_date: date,
  repo_count: count,
  audit_md_b64: Buffer.from(md, 'utf8').toString('base64')
} }];

// prépare le body du PUT contents (avec sha si le fichier existe déjà)
const prev = $("Formater le rapport").first().json;
const getResp = $input.first().json;
const sha = getResp && getResp.sha ? getResp.sha : null;
const body = {
  message: "Audit GitHub " + prev.audit_date + " [skip ci]",
  content: prev.audit_md_b64,
  branch: "main"
};
if (sha) body.sha = sha;
return [{ json: { audit_date: prev.audit_date, commit_body: JSON.stringify(body) } }];

// Prépare le rapport complet en binaire pour sendDocument Telegram
const item = $input.first().json;
const buffer = Buffer.from(item.rapport_complet, 'utf8');
const bin = await this.helpers.prepareBinaryData(buffer, 'audit-' + item.audit_date + '.md', 'text/markdown');
return [{ json: { audit_date: item.audit_date, caption: '📄 Rapport complet — audit GitHub du ' + item.audit_date }, binary: { document: bin } }];
